shader.source:
half4 main(float2 p) {
  float2 uv = (p - 0.5 * md_resolution) / min(md_resolution.x, md_resolution.y);
  float t = md_time * speed;
  float field = uv.y + 0.17 * sin(uv.x * 4.0 + t) + 0.08 * sin(uv.x * 7.0 - t * 0.7);
  float edge = abs(fract(field * spacing) - 0.5);
  float line = 1.0 - smoothstep(0.018, 0.045, edge);
  return mix(base, ink, half(line * 0.55));
}
